            new Quote { Id = "https://pt.wikiquote.org/wiki/Érico_Veríssimo", Text = "Felicidade é a certeza de que a nossa vida não está se passando inutilmente.", Author = "Érico Veríssimo" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Érico_Veríssimo", Text = "Olha as estrelas. Enquanto elas brilharem haverá esperança na vida.", Author = "Érico Veríssimo" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Érico_Veríssimo", Text = "Os livros escolares, cujo objetivo é ensinar-nos a história da nossa terra e do nosso povo, são em geral escritos num espírito maniqueísta, seguindo as clássicas antíteses –os bons e os maus, os heróis e os covardes, os santos e os bandidos.", Author = "Érico Veríssimo" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Érico_Veríssimo", Text = "Via de regra, não se empregam nesses compêndios as cores intermediárias, pois os seus autores parecem desconhecer a virtude dos matizes e o truísmo de que a História não pode ser escrita apenas em preto e branco.", Author = "Érico Veríssimo" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Érico_Veríssimo", Text = "E eu acho, meu caro, que cada um de nós tem nas suas mais remotas cavernas interiores um troglodita adormecido que, submetido a um certo tipo de estímulo, vem rapidamente à tona de nosso ser e se transforma num déspota totalitário capaz de todas as bestialidades.", Author = "Érico Veríssimo" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Érico_Veríssimo", Text = "Acho que o homem é um animal agressivo, não há dúvida, mas a diferença entre ele e o lobo é que a criatura humana pensa, é ao mesmo sujeito e objeto, tem a capacidade de ver o seu lado negativo e deplorá-lo. Não ignora que tem um futuro. Tem também a consciência de sua finitude. É - salvo as aberrações - capaz de compaixão, de contrição e de amor. E a crise do mundo moderno não será principalmente a falta de amor?", Author = "Érico Veríssimo" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Érico_Veríssimo", Text = "O fio que prende a sua fé deve ser do melhor aço e portanto resistente e ao mesmo tempo flexível. Fé sem flexibilidade, fé sem dúvida pode acabar em fanatismo.", Author = "Érico Veríssimo" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Érico_Veríssimo", Text = "Ora, menino, um ser humano não é uma moeda apenas, com verso e reverso. É um poliedro, com milhares de faces. E há milhares de maneiras de ver uma pessoa, um ato, um fato.", Author = "Érico Veríssimo" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Érico_Veríssimo", Text = "Comunista é o pseudônimo que os conservadores, os conformistas e os saudosistas do fascismo inventaram para designar simplisticamente todo o sujeito que clama e luta por justiça social.", Author = "Érico Veríssimo" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Érico_Veríssimo", Text = "Quem está com fome fica surdo até mesmo à voz de Deus.", Author = "Érico Veríssimo" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Érico_Veríssimo", Text = "Desde que, adulto, comecei a escrever romances, tem-me animado até hoje a idéia de que o menos que o escritor pode fazer, numa época de atrocidades e injustiças como a nossa, é acender a sua lâmpada, fazer luz sobre a realidade de seu mundo, evitando que sobre ele caia a escuridão, propícia aos ladrões, aos assassinos e aos tiranos. Sim, segurar a lâmpada, a despeito da náusea e do horror. Se não tivermos uma lâmpada elétrica, acendamos o nosso toco de vela ou, em último caso, risquemos fósforos repetidamente, como um sinal de que não desertamos nosso posto.", Author = "Érico Veríssimo" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Érico_Veríssimo", Text = "Nenhum escritor pode criar do nada. Mesmo quando ele não sabe, está usando experiências vividas, lidas ou ouvidas, e até mesmo pressentidas por uma espécie de sexto sentido.", Author = "Érico Veríssimo" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Érico_Veríssimo", Text = "Sei que não sou, nunca fui um writer's writer, um escritor para escritores. Não sou inovador, não trouxe nenhuma contribuição original para a arte do romance. Tenho dito, escrito repetidamente que me considero, antes de mais nada, um contador de histórias.", Author = "Érico Veríssimo" },
            new Quote { Id = "https://pt.wikiquote.org/wiki/Érico_Veríssimo", Text = "Todos nós somos um mistério para os outros... e para nós mesmos.", Author = "Érico Veríssimo" },
        };
